+static void rgb8_row_to_rgba8(const unsigned char *row, unsigned char *restrict out, uint32_t n)
+{
+    uint32_t i;
+    for(i=0; i < n; i++)
+    {
+        memcpy(out + i * 4, row + i * 3, 3);
+        out[i*4+3] = 255;
+    }
+}
