+       node = ares_llist_node_next(node)) {
+    const char *ipaddr = ares_llist_node_val(node);
+    *match             = ares_htable_strvp_get_direct(hf->iphash, ipaddr);
+    if (*match != NULL) {
+      return ARES_MATCH_IPADDR;
+    }
+  }
