            if (url.authority.base[i])
                total++;
        for (i = 0; i < url.host.len; i++)
            if (url.host.base[i])
                total++;
        for (i = 0; i < url.path.len; i++)
            if (url.path.base[i])
                total++;
        assert(total <= Size * 2);
    }
    return 0;
}
